return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'यस साइटको मिडिया लाइब्ररीलाई Zinn® अब्जेक्ट स्टोरेजमा सार्छ र यसलाई CDN बाट सेवा प्रदान गर्छ। तपाईंको Zinn® ड्यासबोर्डबाट कन्फिगर गरिएको छ — WordPress मा कहिल्यै पनि एक्सेस कुञ्जी टाइप गरिँदैन।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'सुरक्षित गरियो। यसलाई बदल्नको लागि नयाँ मान टाइप गर्नुहोस्।','Filter this list…'=>'यो सूची फिल्टर गर्नुहोस्...','Filter this list'=>'यो सूची फिल्टर गर्नुहोस्','Nothing matches that filter.'=>'त्यो फिल्टरसँग मिल्ने केही छैन।','Add a row'=>'पंक्ति थप्नुहोस्','Remove this row'=>'यो पङ्क्ति हटाउनुहोस्','Remove'=>'हटाउनुहोस्','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — सिंहावलोकन','Overview'=>'अवलोकन','Every Zinn® plugin on this site, and whether it is working.'=>'यस साइटमा भएका प्रत्येक Zinn® प्लगइन, र यो काम गरिरहेको छ कि छैन।','No connection is needed for this plugin.'=>'यस प्लगइनका लागि कुनै जडान आवश्यक छैन।','Open settings'=>'सेटिङहरू खोल्नुहोस्','You do not have permission to change these settings.'=>'तपाईंलाई यी सेटिङहरू परिवर्तन गर्ने अनुमति छैन।','Settings sections'=>'सेटिङ खण्डहरू','Support'=>'समर्थन','Save changes'=>'परिवर्तनहरू सुरक्षित गर्नुहोस्','Tools'=>'उपकरणहरू','Export settings'=>'निर्यात सेटिङहरू','Reset to defaults'=>'पूर्वनिर्धारित मानहरूमा रिसेट गर्नुहोस्','This puts every setting on this plugin back to its default. Continue?'=>'यसले यस प्लगइनका सबै सेटिङहरूलाई तिनीहरूको पूर्वनिर्धारित स्थितिमा फर्काउँछ। जारी राख्ने?','Diagnostics for support'=>'समर्थनका लागि निदान','Import a settings file'=>'सेटिङ फाइल आयात गर्नुहोस्','Import'=>'आयात गर्नुहोस्','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'निर्यात गरिएका फाइलहरूमा कहिल्यै पनि पासवर्ड, टोकन वा API कुञ्जीहरू हुँदैनन् — तपाईंले नयाँ साइटमा ती फेरि प्रविष्ट गर्नुपर्नेछ।','Settings saved.'=>'सेटिङहरू सेभ गरियो।','Every setting on this plugin is back to its default.'=>'यस प्लगइनका प्रत्येक सेटिङहरू तिनीहरूको पूर्वनिर्धारित स्थितिमा फर्किएका छन्।','Done.'=>'सम्पन्न भयो।','That action is not available.'=>'त्यो कार्य उपलब्ध छैन।','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'त्यो फाइल पढ्न सकिएन। Zinn® प्लगइनबाट एक्सपोर्ट गरिएको सेटिङ्स फाइल छान्नुहोस्।','That file is too large to be a settings export.'=>'त्यो फाइल सेटिंग्स निर्यात हुनका लागि धेरै ठूलो छ।','That file is not a Zinn® settings export.'=>'त्यो फाइल Zinn® सेटिङ्स निर्यात होइन।','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'त्यो फाइल फरक प्लगइन (%s) बाट निर्यात गरिएको हो, त्यसैले यसलाई यहाँ आयात गर्दा यो प्लगइनले नबुझ्ने सेटिङहरू भण्डारण हुनेछन्।','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d सेटिङ आयात गरियो। पासवर्ड र API कुञ्जीहरू निर्यातमा समावेश हुँदैनन्, त्यसैले तिनीहरूलाई फेरि प्रविष्ट गर्नुहोस्।' . "\0" . '%d सेटिङहरू आयात गरिएका छन्। पासवर्डहरू र API कुञ्जीहरू निर्यातमा कहिल्यै पनि हुँदैनन्, त्यसैले तिनीहरूलाई फेरि प्रविष्ट गर्नुहोस्।','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® ले टोकन फर्काएन। यस साइटमा कुनै पनि परिवर्तन गरिएको छैन।','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'यो साइट अब Zinn® मिडिया अफलोडमा जडान गरिएको छैन। नयाँ अपलोडहरू यसै सर्भरमा रहनेछन्। यसलाई आफ्नो Zinn Digital® ड्यासबोर्डबाट फेरि जोडा बनाउनुहोस्।','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® ले HTTP %d सus उत्तर दियो।','Disconnected by Zinn Digital®.'=>'Zinn Digital® द्वारा डिस्कनेक्ट गरियो।','Connected'=>'जडित','Connecting…'=>'जोडदै छ…','Connected, but something needs attention'=>'जडान गरिएको छ, तर केही कुरामा ध्यान दिनुपर्छ','Not connected'=>'जडित छैन','Running on your own account'=>'तपाईंको आफ्नै खातामा चल्दैछ','We could not check this'=>'हामी यसको जाँच गर्न सकेनौं','This plugin did not say why. Send a diagnostics report and we will look.'=>'यो प्लगइनले किन भन्यो भन्ने खुलाएको छैन। एउटा डायग्नोस्टिक्स रिपोर्ट पठाउनुहोस्, हामी यसलाई हेर्नेछौँ।','Connection status'=>'जडान स्थिति','Last checked %s ago.'=>'%s अगाडि अन्तिम पटक जाँच गरिएको थियो।','(opens in a new tab)'=>'(नयाँ ट्याबमा खुल्छ)','Send this to Zinn® support'=>'Zinn® समर्थनमा यसलाई पठाउनुहोस्','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'ଠାକୁର यही पठाइनेछ — अरू केही होइन, र कुनै लुकेको कुरा छैन। यसमा तपाईंका पासवर्डहरू, टोकनहरू र API कुञ्जीहरू समावेश छैनन्।','The diagnostics report that will be sent'=>'पठाइने डायग्नोस्टिक्स प्रतिवेदन','Copy to clipboard'=>'क्लिपबोर्डमा प्रतिलिपि गर्नुहोस्','Send this report to Zinn® support'=>'यो रिपोर्ट Zinn® समर्थनलाई पठाउनुहोस्','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'हामी तपाईंका लागि समर्थन टिकट खोल्छौं र इमेलमार्फत जवाफ दिन्छौं। यदि तपाईं यसलाई पठाउन चाहनुहुन्न भने, यसलाई माथि प्रतिलिपि गर्नुहोस् र आफैं टिकटमा टाँस्नुहोस्।','Copied'=>'कपी गरियो','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'यो सर्भर (%s) बाट Zinn Digital® मा पुग्न सकिएन। माथिको प्रतिलिपि (report) कपि गर्नुहोस् र यसको सट्टा टिकट खोल्नुहोस् — तपाईँको सेटिङमा कुनै पनि कुरा गलत छैन।','Sent. Zinn® support has your report and will reply by email.'=>'Zinn® समर्थनले तपाइँको प्रतिवेदन प्राप्त गरेको छ र इमेल मार्फत जवाफ दिनेछ।','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Zinn® समर्थनले तपाईंको रिपोर्ट प्राप्त गरेको छ — सन्दर्भ %s — र इमेलमार्फत जवाफ दिनेछ।','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'तपाईंले छोटो समयमै धेरै रिपोर्टहरू पठाउनुभएको छ। केही मिनेट पर्खनुहोस् र फेरि प्रयास गर्नुहोस् — अघिल्ला रिपोर्टहरू पुगिसकेका छन्।','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® ले अहिले रिपोर्ट स्वीकार गर्न सकेन — यो हाम्रो तर्फबाट हो, तपाईंको तर्फबाट होइन। केही समयपछि फेरि प्रयास गर्नुहोस्, वा माथिको रिपोर्टलाई टिकटमा प्रतिलिपि गर्नुहोस्।','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'प्रतिवेदन अस्वीकार गरियो (HTTP %d)। यसलाई माथि प्रतिलिपि गर्नुहोस् र त्यो नम्बर उल्लेख गर्दै टिकट खोल्नुहोस्।','%s — guides and services'=>'%s — गाइडहरू र सेवाहरू','User guides'=>'प्रयोगकर्ता निर्देशिकाहरू','Read the %s user guide'=>'%s प्रयोगकर्ता गाइड पढ्नुहोस्','Hide this'=>'यो लुकाउनुहोस्','Zinn® hosting for WordPress'=>'WordPress को लागि Zinn® होस्टिङ','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक ब्याकअपहरू, नि:शुल्क बसाइँसराइ र एकभन्दा बढी साइटहरू सञ्चालन गर्ने व्यक्तिहरूका लागि तयार पारिएको नियन्त्रण प्यानल।','The Zinn® marketplace'=>'Zinn® बजार','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'स्थापित साइटहरू, डोमेनहरू र लिङ्क प्लेसमेन्टहरू खरिद र बिक्री गर्नुहोस्, दुवै पक्ष सन्तुष्ट नभएसम्म पैसा सुरक्षित रूपमा राखिन्छ।','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — यसैमा जीवन बिताउने व्यक्तिहरूलाई काममा लगाउनुहोस्','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'हाम्रो विश्वव्यापी फ्रिलान्स बजार: लेखकहरू, डिजाइनरहरू, विकासकर्ताहरू र SEO विशेषज्ञहरूबाट १०,००० भन्दा बढी तयार सेवाहरू ब्राउज गर्नुहोस्, वा परियोजना पोस्ट गरेर उनीहरूलाई बोली लगाउन दिनुहोस्।','Media Offload'=>'मिडिया अफलोड','Connection'=>'जडान','What gets moved'=>'के सारिन्छ','How media is served'=>'मिडिया कसरी प्रस्तुत गरिन्छ','Move a batch now'=>'अहिले नै ब्याच सार्नुहोस्','Media already moved is never affected by a change here — its address does not change.'=>'यहाँ परिवर्तन गरिएको मिडियामा कुनै असर पर्दैन — यसको ठेगाना परिवर्तन हुँदैन।','New uploads'=>'नयाँ अपलोडहरू','Move new uploads to Zinn® storage as they arrive'=>'नयाँ अपलोडहरू आउनासाथ Zinn® स्टोरेजमा सार्नुहोस्','Existing media'=>'अवस्थित मिडिया','Keep moving the media library that is already here'=>'यहाँ भएको मिडिया लाइब्रेरी सार्न जारी राख्नुहोस्','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'प्रति घण्टा केही फाइलहरू, पृष्ठभूमिमा, जहाँ रोकिएको थियो त्यहीँबाट सुरु गर्दै। यसलाई बन्द गर्दा यो रोकिन्छ; पहिले नै सारिसकिएका कुनै पनि कुरा फर्केर आउँदैनन्।','Files per hourly pass'=>'प्रति घण्टा पास फाइलहरू','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'प्रत्येक संलग्न with धेरै फाइलहरू छन् र प्रत्येक एक पूर्ण अपलोड हो। यसलाई उदार कार्यान्वयन सीमा भएको छिटो होस्टमा बढाउनुहोस्; यदि पासहरू छोटो काटिँदैछन् भने यसलाई घटाउनुहोस्।','Leave files smaller than'=>'भन्दा साना फाइलहरू छोड्नुहोस्','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'किलोबाइटहरू। डिस्कमा बचत हुनेभन्दा थप जडानमा सानो आइकनको लागत बढी हुन्छ, त्यसैले यसलाई सार्ने कुनै कारण विरलै हुन्छ। सबै कुरा सार्नको लागि ० मा सेट गर्नुहोस्।','Never move these types'=>'यी प्रकारहरू कहिल्यै नसार्नुहोस्','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'प्लगइनले डिस्कबाट सीधै फाइल पढ्दा उपयोगी — फन्ट, फर्म बिल्डरले छाप लगाउने PDF, प्लेयरले खोज्ने अडियो फाइल।','These two are the ones to be careful with — read each description before changing it.'=>'यी दुईवटामा सावधानी अपनाउनुपर्छ — परिवर्तन गर्नुअघि प्रत्येक विवरण पढ्नुहोस्।','Serve from Zinn® storage'=>'Zinn® भण्डारणबाट सेवा दिनुहोस्','Point image and file addresses at Zinn® storage'=>'Zinn® भण्डारणमा पोइन्ट छवि र फाइल ठेगानाहरू','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'बन्द छ, फाइलहरू अपलोड गरिएका छन् तर अझै पनि यसै सर्भरबाट उपलब्ध गराइँदैछन् — जुन तपाईंले सबै कुरा आइपुगेको छैन भनी जाँच्ने क्रममा सुरक्षित अवस्था हो। चालु छ, आगन्तुकहरूलाई भण्डारणबाट उपलब्ध गराइन्छ र यो सर्भरले ट्राफिक बोक्न बन्द गर्छ।','Free the disk space'=>'डिक्स ठाउँ खाली गर्नुहोस्','Delete the local copy once every size has uploaded'=>'हरेक साइज अपलोड भइसकेपछि स्थानीय प्रतिलिपि (लोकल कपी) मेटाउनुहोस्','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'यो अफलोडिङको बिन्दु हो, र यो अपरिवर्तनीय आधा भाग पनि हो। “Serve from Zinn® storage” अन नभएसम्म र तपाईंले आफ्नो साइट जाँच नगरेसम्म यसलाई बन्द राख्नुहोस्—कुनै कुरा छुटेको भए स्थानीय प्रतिलिपि मात्र एउटा यस्तो कुरा हो जसले तपाईंलाई बचाउँछ।','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'स्थानीय प्रतिहरू मेटाउने काम यो स्क्रिनबाट पूर्ववत् गर्न सकिँदैन। पहिले ब्याकअप लिनुहोस् — Zinn® Connector प्लगइनले तपाईंको लागि त्यो गर्न सक्छ।','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'यो साइट अहिले Zinn® स्टोरेजसँग जोडिएको छैन, त्यसैले मिडिया सार्ने कुनै ठाउँ छैन।','%d attachment moved.'=>'%d एटेचमेन्ट सारियो।' . "\0" . '%d संलग्नकहरू सारिए।','This site is not connected to Zinn® storage.'=>'यो साइट Zinn® storage सँग जोडिएको छैन।','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'केही पनि बिग्रिएको छैन — यो केवल जोडिएको छैन। त्यसो नभएसम्म मिडिया यसै सर्भरमा रहन्छ।','Connected, but the last upload failed.'=>'जडान भयो, तर अन्तिम अपलोड असफल भयो।','Try a batch now'=>'अहिले नै ब्याच प्रयास गर्नुहोस्','Connected. Every attachment has been moved.'=>'सम्बद्ध भयो। प्रत्येक संलग्नक सारिएको छ।','Connected. %1$s of %2$s attachments still on this server.'=>'जडान भयो। %1$s मध्ये %2$s संलग्नकहरू अझै पनि यसै सर्भरमा छन्।','Moved so far'=>'अहिले सम्म सारिएको','%1$s files, %2$s'=>'%1$s फाइलहरू, %2$s','Still on this server'=>'अझै यसै सर्भरमा छ','%1$s of %2$s attachments'=>'%2$s मध्ये %1$s संलग्नकहरू','Served from'=>'यसबाट सेवा दिइएको','this server'=>'यो सर्भर','Connect this site'=>'यो साइट जडान गर्नुहोस्','Open your Zinn Digital® dashboard, go to Storage → Media offload, and press “Pair a site”. Paste the code below.'=>'तपाईंको Zinn Digital® ड्यासबोर्ड खोल्नुहोस्, Storage → Media offload मा जानुहोस्, र “Pair a site” थिच्नुहोस्। तलको कोड टाँस्नुहोस्।','Pairing code'=>'जोडी कोड','Disconnect this site'=>'यो साइट विच्छेदन गर्नुहोस्','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'नयाँ अपलोडहरू यसै सर्भरमा रहनेछन्। पहिले नै सारिएका मिडियाहरूले काम गरिरहनेछन् — तिनीहरूको ठेगाना परिवर्तन हुँदैन।','You do not have permission to manage this site.'=>'तपाईंलाई यो साइट व्यवस्थापन गर्ने अनुमति छैन।','Paste the pairing code from your Zinn Digital® dashboard.'=>'तपाईंको Zinn Digital® ड्यासबोर्डबाट जोडी कोड टाँस्नुहोस्।','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'सम्बद्ध भयो। अब उप्रान्त नयाँ अपलोडहरू Zinn Digital® मा भण्डारण गरिनेछन्, र तपाईंको अवस्थित मिडिया पृष्ठभूमिमा सर्नेछ।','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'सम्पर्कविच्छेद भयो। पहिले सारिसकेका मिडियाहरूले काम गरिरहन्छन्; नयाँ अपलोडहरू यसै सर्भरमा रहन्छन्।','That file could not be read from this server, so nothing was uploaded.'=>'त्यो फाइल यो सर्भरबाट पढ्न सकिएन, त्यसैले केही पनि अपलोड गरिएन।','This site could not stream the upload, so nothing was sent.'=>'यो साइटले अपलोड स्ट्रिम गर्न सकेन, त्यसैले केही पनि पठाइएन।','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'यो फाइल %1$s हो र यस साइटको PHP मा cURL छैन, त्यसैले यसले अपलोड गर्न सक्ने अधिकतम साइज %2$s हो।','The upload could not be completed.'=>'अपलोड पूरा हुन सकेन।','Storage refused the upload (HTTP %d).'=>'भण्डारणले अपलोड अस्वीकार गर्यो (HTTP %d)।','Style preset'=>'शैली प्रिसेट','A starting point. Anything below overrides it.'=>'एक सुरुवाती बिन्दु। यसभन्दा तलका जुनसुकै कुराले यसलाई ओभरराइड गर्दछ।','Use my own colours and sizes'=>'मेरो आफ्नै रङ र साइजहरू प्रयोग गर्नुहोस्','Leave this off and the preset is used exactly as it is.'=>'यसलाई बन्द राख्नुहोस् र प्रिसेट जस्तो छ त्यस्तै प्रयोग गरिन्छ।','See the Zinn Digital® release notes.'=>'Zinn Digital® को रिलिज नोटहरू हेर्नुहोस्।','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड गरिएको अपडेटले यसको इन्टिग्रिटी चेक (सत्यता परीक्षण) पास गर्न सकेन र इन्स्टल गरिएको छैन।']];